"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "../../lib/utils";

// Textarea: generated by UIX from the design system. Same variants and sizes as the Figma component.

const textareaVariants = cva(
  "block min-h-[112px] w-full resize-y px-3 py-[10px] outline-none transition-colors text-body-medium text-fg-primary placeholder:text-fg-tertiary disabled:text-fg-disabled rounded-md",
  {
    variants: {
      appearance: {
        outline: "border border-line-default bg-surface hover:border-line-strong focus-visible:ring-3 focus-visible:ring-line-focus focus-visible:border-line-focus disabled:cursor-not-allowed disabled:bg-disabled",
        filled: "border border-transparent bg-subtle hover:bg-muted focus-visible:ring-3 focus-visible:ring-line-focus focus-visible:border-line-focus disabled:cursor-not-allowed disabled:bg-disabled",
        underline: "rounded-none border-0 border-b bg-transparent px-0 border-line-default hover:border-line-strong focus-visible:border-b-2 focus-visible:border-line-focus disabled:cursor-not-allowed",
      },
    },
    compoundVariants: [
      { appearance: "underline", class: "rounded-none px-0" },
    ],
    defaultVariants: {
      appearance: "outline",
    },
  },
);

export interface TextareaProps
  extends React.TextareaHTMLAttributes<HTMLTextAreaElement>,
    VariantProps<typeof textareaVariants> {
  label?: React.ReactNode;
  /** Right-aligned note next to the label, for example "Optional". */
  secondaryLabel?: React.ReactNode;
  /** Message under the field. */
  feedback?: React.ReactNode;
  /** Same as feedback. */
  helper?: React.ReactNode;
  /** Error message; also marks the field invalid and replaces the feedback. */
  error?: string;
}

const Textarea = React.forwardRef<HTMLTextAreaElement, TextareaProps>(
  ({ className, appearance, label, secondaryLabel, feedback, helper, error, required, id, disabled, ...props }, ref) => {
    const autoId = React.useId();
    const fieldId = id ?? autoId;
    const hintId = fieldId + "-hint";
    const message = error || feedback || helper;
    const hint = message ? { "aria-describedby": hintId } : {};
    return (
      <div data-slot="textarea" data-kind="field" className={cn("skin-quiet flex w-full flex-col gap-1-5", className)}>
        {label ? (
          <div className="flex items-baseline justify-between gap-2">
            <label htmlFor={fieldId} className={cn("text-label-medium text-fg-primary", disabled && "text-fg-disabled")}>
              {label}
              {required ? <span aria-hidden className="ml-0.5 text-fg-danger">*</span> : null}
            </label>
            {secondaryLabel ? <span className="text-body-small text-fg-tertiary">{secondaryLabel}</span> : null}
          </div>
        ) : null}
        <textarea ref={ref} data-kind="field" id={fieldId} disabled={disabled} required={required} aria-invalid={!!error} {...hint} className={cn(textareaVariants({ appearance }), error && "border-line-danger hover:border-line-danger focus-visible:border-line-danger focus-visible:ring-line-danger")} {...props} />
        {message ? (
          <p id={hintId} className={cn("text-body-small text-fg-secondary", error && "text-fg-danger")}>
            {message}
          </p>
        ) : null}
      </div>
    );
  },
);
Textarea.displayName = "Textarea";

export { Textarea, textareaVariants };
